pub fn serialize_rdt(
    output: &caliper_docgen_core::types::ExtractionOutput,
    include_unexported: bool,
) -> serde_json::Result<String> {
    caliper_docgen_core::pipeline::rdt::serialize(output, include_unexported)
}

