            ("linux", "x86_64", "musl") => "linux-x64-musl",
            ("linux", "aarch64", "gnu") => "linux-arm64-gnu",
            ("linux", "aarch64", "musl") => "linux-arm64-musl",
            ("windows", "x86_64", _) => "win32-x64",
