    const DARWIN_ARM64: TsrsPlatform = TsrsPlatform { package: "darwin-arm64", exe: "tsrs" };

    fn tree() -> (tempfile::TempDir, Utf8PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
        (dir, root)
    }

    fn touch(path: &Utf8Path) -> Utf8PathBuf {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, "").unwrap();
        path.to_owned()
    }

    fn find(project: &Utf8Path, explicit: Option<&Utf8Path>, binary_dir: Option<&Utf8Path>) -> Result<Utf8PathBuf, String> {
        find_tsc_on(Ok(DARWIN_ARM64), project, explicit, binary_dir)
    }

