fn binary_dir() -> Option<camino::Utf8PathBuf> {
    let located = std::env::current_exe().map_err(|error| error.to_string()).and_then(|exe| {
        let exe = camino::Utf8PathBuf::from_path_buf(exe).map_err(|exe| format!("{} is not UTF-8", exe.display()))?;
        caliper_docgen_core::canonical_path::canonicalize(&exe).map_err(|error| format!("{exe}: {error}"))
    });
    match located {
        Ok(exe) => exe.parent().map(camino::Utf8Path::to_path_buf),
        Err(reason) => {
            tracing::warn!("cannot locate the caliper-docgen binary to find the tsrs installed with it: {reason}");
            None
        }
    }
}

